describe('Sticky Footer Navigation on Mobile', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display sticky footer navigation on mobile viewport', () => {
    // Set viewport to mobile
    cy.viewport('iphone-x');

    // Verify footer navigation is visible
    cy.get('[data-testid="footer-nav"]').should('be.visible');
    cy.get('[data-testid="footer-nav"]').should('contain', 'Home');
    cy.get('[data-testid="footer-nav"]').should('contain', 'About');
    cy.get('[data-testid="footer-nav"]').should('contain', 'Contact');

    // Verify footer navigation is sticky
    cy.get('[data-testid="footer-nav"]').should('have.style', 'position', 'sticky');
    cy.get('[data-testid="footer-nav"]').should('have.style', 'top', '0px');

    // Verify navigation links are clickable
    cy.get('[data-testid="footer-nav"]').find('a').should('be.visible');
    cy.get('[data-testid="footer-nav"]').find('a').first().should('have.attr', 'href');

    // Verify footer content is visible
    cy.get('[data-testid="footer-content"]').should('be.visible');
    cy.get('[data-testid="footer-content"]').should('contain', 'Copyright © 2023');
  });

  it('should maintain sticky footer navigation when scrolling down', () => {
    // Set viewport to mobile
    cy.viewport('iphone-x');

    // Scroll down to test stickiness
    cy.get('[data-testid="main-content"]').scrollTo('bottom');

    // Verify footer navigation is still sticky
    cy.get('[data-testid="footer-nav"]').should('have.style', 'position', 'sticky');
    cy.get('[data-testid="footer-nav"]').should('have.style', 'top', '0px');

    // Verify footer navigation content is still visible
    cy.get('[data-testid="footer-content"]').should('be.visible');
    cy.get('[data-testid="footer-content"]').should('contain', 'Copyright © 2023');

    // Verify footer navigation links are still clickable
    cy.get('[data-testid="footer-nav"]').find('a').should('be.visible');
    cy.get('[data-testid="footer-nav"]').find('a').first().should('have.attr', 'href');
  });
});
